"""Clean an autogenerated migration (run after `alembic revision --autogenerate`).

Our enums are text + CHECK (`app.db.base.text_enum`). Alembic renders each one as
`sa.Enum(..., create_constraint=True)` plus the CHECK twice (once unnamed, once with
the naming convention), which would create duplicate constraints. This rewrites the
column type to `sa.String(length=N)` and keeps only the convention-named CHECK.

    .venv/Scripts/python scripts/tidy_migration.py alembic/versions/<file>.py
"""

import re
import sys
from pathlib import Path

ENUM = re.compile(r"sa\.Enum\(\n(?:\s+.*\n)*?\s+length=(\d+),\n\s+\)")
UNNAMED_CHECK = re.compile(
    r"\n\s+sa\.CheckConstraint\(\n?\s*\"[^\"]*\",\s*\n?\s*name=\"[a-z_]+\",?\n?\s*\),"
)
MARKERS = (
    "    # ### commands auto generated by Alembic - please adjust! ###\n",
    "    # ### end Alembic commands ###\n",
)


def tidy(source: str) -> str:
    source = ENUM.sub(lambda m: f"sa.String(length={m.group(1)})", source)
    source = UNNAMED_CHECK.sub("", source)
    for marker in MARKERS:
        source = source.replace(marker, "")
    return source


if __name__ == "__main__":
    for name in sys.argv[1:]:
        path = Path(name)
        path.write_text(tidy(path.read_text(encoding="utf-8")), encoding="utf-8")
        print(f"tidied {path}")
